package co.edu.unbosque.horarios.service;
import com.lowagie.text.*; import com.lowagie.text.pdf.*; import org.apache.poi.xssf.usermodel.XSSFWorkbook; import org.springframework.stereotype.Service; import java.io.*;
@Service public class ExportService {
 private final ScheduleService schedules; public ExportService(ScheduleService s){schedules=s;}
 public byte[] pdf(Long id){try(var out=new ByteArrayOutputStream()){var schedule=schedules.get(id);var doc=new Document(PageSize.A4.rotate());PdfWriter.getInstance(doc,out);doc.open();doc.add(new Paragraph("Universidad El Bosque · Horario "+schedule.period(),FontFactory.getFont(FontFactory.HELVETICA_BOLD,18)));doc.add(new Paragraph("Versión "+schedule.version()+" · "+schedule.status()));var table=new PdfPTable(6);for(String h:new String[]{"Curso","Sección","Docente","Aula","Día","Hora"})table.addCell(h);for(var x:schedule.sessions()){table.addCell(x.courseCode()+" · "+x.courseName());table.addCell(String.valueOf(x.sectionNumber()));table.addCell(x.teacher());table.addCell(x.classroom());table.addCell(String.valueOf(x.day()));table.addCell(x.start()+" - "+x.end());}doc.add(table);doc.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException(e);}}
 public byte[] xlsx(Long id){try(var book=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var sheet=book.createSheet("Horario");var header=sheet.createRow(0);String[] cols={"Código","Curso","Sección","Docente","Aula","Día","Inicio","Fin"};for(int i=0;i<cols.length;i++)header.createCell(i).setCellValue(cols[i]);int row=1;for(var x:schedules.get(id).sessions()){var r=sheet.createRow(row++);r.createCell(0).setCellValue(x.courseCode());r.createCell(1).setCellValue(x.courseName());r.createCell(2).setCellValue(x.sectionNumber());r.createCell(3).setCellValue(x.teacher());r.createCell(4).setCellValue(x.classroom());r.createCell(5).setCellValue(x.day());r.createCell(6).setCellValue(x.start());r.createCell(7).setCellValue(x.end());}for(int i=0;i<cols.length;i++)sheet.autoSizeColumn(i);book.write(out);return out.toByteArray();}catch(Exception e){throw new IllegalStateException(e);}}
}
